.darma-loader-darma-b10-slot-reels { --accent: var(--loader-color, #f43f5e); --accent-2: var(--loader-secondary-color, #fbbf24); width: var(--loader-size, 92px); height: calc(var(--loader-size, 92px) * .7); display: flex; gap: calc(var(--loader-size, 92px) * .04); background: #1f2937; border-radius: calc(var(--loader-size, 92px) * .08); padding: calc(var(--loader-size, 92px) * .05); box-sizing: border-box; }
.darma-loader-darma-b10-slot-reels span { flex: 1; overflow: hidden; border-radius: calc(var(--loader-size, 92px) * .04); background: #0f172a; position: relative; }
.darma-loader-darma-b10-slot-reels span::before { content: ''; position: absolute; left: 0; right: 0; top: 0; height: 300%; background: repeating-linear-gradient(var(--accent) 0 16.66%, var(--accent-2) 16.66% 33.33%); animation: darma-loader-darma-b10-slot-reels-reel calc(var(--loader-speed, 1s) * .8) linear infinite; }
.darma-loader-darma-b10-slot-reels span:nth-child(2)::before { animation-duration: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b10-slot-reels span:nth-child(3)::before { animation-duration: calc(var(--loader-speed, 1s) * 1); }
@keyframes darma-loader-darma-b10-slot-reels-reel { to { transform: translateY(-33.33%); } }

